think-table-diff.solution:
def table_diff(n, old, new, default):
    def run(table, s):
        for pat, a in table:
            if all(x == "-" or x == y for x, y in zip(pat, s)):
                return a
        return default
    out = []
    for p in itertools.product("NY", repeat=n):
        s = "".join(p)
        a, b = run(old, s), run(new, s)
        if a != b:
            out.append([s, a, b])
    return out

think-vending-machine.solution:
def vending(prices, stock, bank, events):
    coins = {d: c for d, c in bank}
    denoms = sorted(coins, reverse=True)
    stock = dict(stock)
    credit = 0
    escrow = {}
    out = []
    for ev in events:
        kind = ev[0]
        if kind == "coin":
            v = ev[1]
            if v not in coins:
                out.append("REJECT %d" % v)
            else:
                escrow[v] = escrow.get(v, 0) + 1
                credit += v
                out.append("CREDIT %d" % credit)
        elif kind == "refund":
            out.append("REFUND %d" % credit)
            credit = 0
            escrow = {}
        else:
            item = ev[1]
            if item not in prices:
                out.append("INVALID")
            elif stock.get(item, 0) == 0:
                out.append("SOLD_OUT")
            elif credit < prices[item]:
                out.append("NEED %d" % (prices[item] - credit))
            else:
                change = credit - prices[item]
                pool = {d: coins[d] + escrow.get(d, 0) for d in denoms}
                rem = change
                used = {}
                for d in denoms:
                    k = min(pool[d], rem // d)
                    used[d] = k
                    rem -= k * d
                if rem != 0:
                    out.append("EXACT_CHANGE_ONLY")
                else:
                    for d in denoms:
                        coins[d] = pool[d] - used[d]
                    stock[item] -= 1
                    credit = 0
                    escrow = {}
                    out.append("VEND %s %d" % (item, change))
    return [out, [[d, coins[d]] for d in denoms]]

