def cover_transitions(transitions, start):
    adj = collections.defaultdict(list)
    for a, e, b in transitions:
        adj[a].append((e, b))
    path = {start: []}
    queue = collections.deque([start])
    while queue:
        s = queue.popleft()
        for e, b in adj[s]:
            if b not in path:
                path[b] = path[s] + [e]
                queue.append(b)
    return [path[a] + [e] for a, e, b in transitions]

